import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-4",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 4" [disableTooltip]="!isActive">
            <p class="hint">Set disableTooltip on a pill to hide its hint.</p>
            <app-pill label="Quiet" variant="info" [disableTooltip]="user?.prefs?.quiet" />
            <app-pill [label]="title" [variant]="statusVariant" [disableTooltip]="items.length === 0" />
            <app-pill label="Keyed" variant="warning" [disableTooltip]="flags['hidden']" />
            <app-pill label="Called" variant="success" [disableTooltip]="isHidden()" />
            @if (disableTooltip) {
                <small>Own flag, unrelated to the pill input</small>
            }
        </app-card>
    `
})
export class Feature004Component {
    isActive = true;
    count = 4;
    disableTooltip = false;
    title = "Title 4";
    statusVariant: PillVariant = "warning";
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: true } ];
    user?: { prefs?: { quiet: boolean } } = { prefs: { quiet: false } };
    flags: Record<string, boolean> = { hidden: false };
    isHidden(): boolean {
        return this.count > 4;
    }
}
